import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';
import NotificationToggle from '../components/NotificationToggle';

const Profile = ({ studyData, tasks }) => {
  const { theme } = useTheme();
  const [isEditing, setIsEditing] = useState(false);
  const [profileData, setProfileData] = useState({
    name: 'Alex Johnson',
    email: 'alex.johnson@example.com',
    school: 'University of Technology',
    major: 'Computer Science',
    year: '3rd Year',
    bio: 'Dedicated student focusing on AI and machine learning. I enjoy problem-solving and building applications that make a difference.',
    avatar: 'https://via.placeholder.com/150/6366F1/FFFFFF?text=AJ'
  });
  
  const pageVariants = {
    initial: { opacity: 0, y: 20 },
    animate: { 
      opacity: 1, 
      y: 0,
      transition: { 
        duration: 0.5,
        ease: "easeOut" 
      }
    },
    exit: { 
      opacity: 0,
      y: -20,
      transition: { 
        duration: 0.3 
      }
    }
  };
  
  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfileData(prev => ({
      ...prev,
      [name]: value
    }));
  };
  
  const handleSubmit = (e) => {
    e.preventDefault();
    setIsEditing(false);
    // In a real app, you would save the profile data to a database here
  };
  
  // Stats calculated from the passed studyData and tasks
  const totalStudyHours = studyData ? studyData.reduce((total, day) => total + day.value / 60, 0).toFixed(1) : 0;
  const completedTasks = tasks ? tasks.filter(task => task.completed).length : 0;
  const totalTasks = tasks ? tasks.length : 0;
  const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
  
  return (
    <motion.div
      initial="initial"
      animate="animate"
      exit="exit"
      variants={pageVariants}
      className="max-w-5xl mx-auto"
    >
      <div className="mb-6 text-center">
        <h1 className={`text-4xl font-bold ${theme.text.primary}`}>
          Profile
        </h1>
        <p className={`text-lg mt-2 ${theme.text.secondary}`}>
          Manage your personal information and track your progress
        </p>
      </div>
      
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Profile Card */}
        <motion.div 
          className={`p-6 rounded-xl ${theme.card} backdrop-blur-lg shadow-lg lg:col-span-2`}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
        >
          <div className="flex flex-col md:flex-row">
            <div className="md:mr-8 mb-4 md:mb-0 flex flex-col items-center">
              <div className="relative">
                <img 
                  src={profileData.avatar} 
                  alt="Profile" 
                  className="rounded-full w-32 h-32 object-cover border-4 border-blue-500"
                />
                {!isEditing && (
                  <motion.button
                    className="absolute bottom-0 right-0 bg-blue-500 text-white p-2 rounded-full shadow-lg"
                    whileHover={{ scale: 1.1 }}
                    whileTap={{ scale: 0.9 }}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" />
                    </svg>
                  </motion.button>
                )}
              </div>
              <div className="mt-4 text-center">
                <h3 className={`text-xl font-bold ${theme.text.primary}`}>{profileData.name}</h3>
                <p className={`text-sm ${theme.text.secondary}`}>{profileData.email}</p>
              </div>
            </div>
            
            <div className="flex-grow">
              {isEditing ? (
                <form onSubmit={handleSubmit}>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className={`block text-sm font-medium mb-1 ${theme.text.secondary}`}>
                        School
                      </label>
                      <input 
                        type="text" 
                        name="school"
                        value={profileData.school}
                        onChange={handleChange}
                        className="w-full px-3 py-2 bg-gray-700 bg-opacity-50 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                      />
                    </div>
                    
                    <div>
                      <label className={`block text-sm font-medium mb-1 ${theme.text.secondary}`}>
                        Major
                      </label>
                      <input 
                        type="text" 
                        name="major"
                        value={profileData.major}
                        onChange={handleChange}
                        className="w-full px-3 py-2 bg-gray-700 bg-opacity-50 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                      />
                    </div>
                    
                    <div>
                      <label className={`block text-sm font-medium mb-1 ${theme.text.secondary}`}>
                        Year
                      </label>
                      <input 
                        type="text" 
                        name="year"
                        value={profileData.year}
                        onChange={handleChange}
                        className="w-full px-3 py-2 bg-gray-700 bg-opacity-50 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                      />
                    </div>
                  </div>
                  
                  <div className="mt-4">
                    <label className={`block text-sm font-medium mb-1 ${theme.text.secondary}`}>
                      Bio
                    </label>
                    <textarea 
                      name="bio"
                      value={profileData.bio}
                      onChange={handleChange}
                      rows="4"
                      className="w-full px-3 py-2 bg-gray-700 bg-opacity-50 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-blue-500"
                    ></textarea>
                  </div>
                  
                  <div className="flex justify-end mt-4">
                    <motion.button
                      type="button"
                      className="px-4 py-2 bg-gray-700 text-white rounded-lg mr-2"
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      onClick={() => setIsEditing(false)}
                    >
                      Cancel
                    </motion.button>
                    <motion.button
                      type="submit"
                      className="px-4 py-2 bg-blue-500 text-white rounded-lg"
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                    >
                      Save
                    </motion.button>
                  </div>
                </form>
              ) : (
                <>
                  <div className="flex justify-between items-center mb-4">
                    <h3 className={`text-xl font-bold ${theme.text.primary}`}>Personal Information</h3>
                    <motion.button
                      className="px-3 py-1.5 bg-blue-500 text-white rounded-lg flex items-center"
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      onClick={() => setIsEditing(true)}
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" viewBox="0 0 20 20" fill="currentColor">
                        <path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" />
                      </svg>
                      Edit
                    </motion.button>
                  </div>
                  
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                    <div>
                      <p className={`text-sm ${theme.text.secondary}`}>School</p>
                      <p className={`${theme.text.primary}`}>{profileData.school}</p>
                    </div>
                    
                    <div>
                      <p className={`text-sm ${theme.text.secondary}`}>Major</p>
                      <p className={`${theme.text.primary}`}>{profileData.major}</p>
                    </div>
                    
                    <div>
                      <p className={`text-sm ${theme.text.secondary}`}>Year</p>
                      <p className={`${theme.text.primary}`}>{profileData.year}</p>
                    </div>
                  </div>
                  
                  <div>
                    <p className={`text-sm ${theme.text.secondary}`}>Bio</p>
                    <p className={`${theme.text.primary}`}>{profileData.bio}</p>
                  </div>
                </>
              )}
            </div>
          </div>
        </motion.div>
        
        {/* Stats Card */}
        <motion.div 
          className={`p-6 rounded-xl ${theme.card} backdrop-blur-lg shadow-lg`}
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ delay: 0.2 }}
        >
          <h3 className={`text-xl font-bold mb-4 ${theme.text.primary}`}>Your Stats</h3>
          
          <div className="space-y-6">
            <div>
              <div className="flex justify-between mb-1">
                <span className={`${theme.text.secondary}`}>Total Study Hours</span>
                <span className={`font-bold ${theme.text.primary}`}>{totalStudyHours}h</span>
              </div>
              <div className="w-full h-2 bg-gray-700 rounded-full">
                <motion.div 
                  className="h-full bg-blue-500 rounded-full"
                  initial={{ width: 0 }}
                  animate={{ width: `${Math.min(totalStudyHours / 50 * 100, 100)}%` }}
                  transition={{ duration: 1, delay: 0.3 }}
                ></motion.div>
              </div>
            </div>
            
            <div>
              <div className="flex justify-between mb-1">
                <span className={`${theme.text.secondary}`}>Task Completion</span>
                <span className={`font-bold ${theme.text.primary}`}>{completedTasks}/{totalTasks}</span>
              </div>
              <div className="w-full h-2 bg-gray-700 rounded-full">
                <motion.div 
                  className="h-full bg-green-500 rounded-full"
                  initial={{ width: 0 }}
                  animate={{ width: `${completionRate}%` }}
                  transition={{ duration: 1, delay: 0.4 }}
                ></motion.div>
              </div>
            </div>
            
            <div>
              <div className="flex justify-between mb-1">
                <span className={`${theme.text.secondary}`}>Streak</span>
                <span className={`font-bold ${theme.text.primary}`}>5 days</span>
              </div>
              <div className="w-full h-2 bg-gray-700 rounded-full">
                <motion.div 
                  className="h-full bg-purple-500 rounded-full"
                  initial={{ width: 0 }}
                  animate={{ width: '50%' }}
                  transition={{ duration: 1, delay: 0.5 }}
                ></motion.div>
              </div>
            </div>
            
            <div>
              <div className="flex justify-between mb-1">
                <span className={`${theme.text.secondary}`}>Focus Score</span>
                <span className={`font-bold ${theme.text.primary}`}>85%</span>
              </div>
              <div className="w-full h-2 bg-gray-700 rounded-full">
                <motion.div 
                  className="h-full bg-yellow-500 rounded-full"
                  initial={{ width: 0 }}
                  animate={{ width: '85%' }}
                  transition={{ duration: 1, delay: 0.6 }}
                ></motion.div>
              </div>
            </div>
          </div>
          
          <div className="mt-8">
            <h4 className={`font-semibold mb-2 ${theme.text.primary}`}>Achievements</h4>
            <div className="grid grid-cols-3 gap-2">
              {[
                { name: 'Early Bird', icon: '🌅', achieved: true },
                { name: 'Bookworm', icon: '📚', achieved: true },
                { name: 'Consistent', icon: '📊', achieved: true },
                { name: 'Fast Learner', icon: '🚀', achieved: false },
                { name: 'Night Owl', icon: '🦉', achieved: false },
                { name: 'Team Player', icon: '👥', achieved: false },
              ].map((achievement, index) => (
                <motion.div 
                  key={index}
                  className={`p-2 rounded-lg text-center ${
                    achievement.achieved ? 'bg-blue-500 bg-opacity-20' : 'bg-gray-700 bg-opacity-30'
                  }`}
                  whileHover={{ scale: 1.05 }}
                >
                  <div className="text-2xl mb-1">{achievement.icon}</div>
                  <div className={`text-xs ${achievement.achieved ? theme.text.primary : theme.text.muted}`}>
                    {achievement.name}
                  </div>
                </motion.div>
              ))}
            </div>
          </div>
          
          <div className="mt-4">
            <h4 className={`font-semibold mb-2 ${theme.text.primary}`}>Settings</h4>
            <div className="p-3 bg-gray-800 bg-opacity-30 rounded-lg">
              <NotificationToggle />
            </div>
          </div>
        </motion.div>
      </div>
      
      {/* Recent Activity */}
      <motion.div 
        className={`p-6 rounded-xl ${theme.card} backdrop-blur-lg shadow-lg mt-6`}
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.3 }}
      >
        <h3 className={`text-xl font-bold mb-4 ${theme.text.primary}`}>Recent Activity</h3>
        
        <div className="space-y-4">
          {[
            { type: 'task', text: 'Completed "React Router Implementation" task', time: '2 hours ago', icon: '✅' },
            { type: 'session', text: 'Completed a 2-hour study session on JavaScript', time: '5 hours ago', icon: '⏱️' },
            { type: 'book', text: 'Read 25 pages of "Design Patterns"', time: 'Yesterday', icon: '📖' },
            { type: 'achievement', text: 'Earned "3-day streak" achievement', time: 'Yesterday', icon: '🏆' },
            { type: 'task', text: 'Created 3 new tasks for Algorithm Study', time: '2 days ago', icon: '📝' },
          ].map((activity, index) => (
            <motion.div 
              key={index}
              className="flex p-3 rounded-lg hover:bg-gray-700 hover:bg-opacity-30 transition"
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.4 + index * 0.1 }}
              whileHover={{ x: 4 }}
            >
              <div className="w-8 h-8 rounded-full bg-gray-800 flex items-center justify-center mr-3 flex-shrink-0">
                <span>{activity.icon}</span>
              </div>
              <div className="flex-grow">
                <p className={`${theme.text.primary}`}>{activity.text}</p>
                <p className={`text-xs ${theme.text.muted}`}>{activity.time}</p>
              </div>
            </motion.div>
          ))}
        </div>
      </motion.div>
    </motion.div>
  );
};

export default Profile; 