import React from 'react';
import { motion } from 'framer-motion';
import { useNotification } from './NotificationContext';

const NotificationToggle = ({ className = '' }) => {
  const { autoNotify, toggleAutoNotify, addNotification } = useNotification();

  const handleToggle = () => {
    toggleAutoNotify();
    addNotification(
      `Notifications ${!autoNotify ? 'enabled' : 'disabled'}`,
      !autoNotify ? 'success' : 'info',
      true // Force notification even if disabled
    );
  };

  return (
    <div className={`flex items-center ${className}`}>
      <span className="text-sm mr-2">Auto Notifications</span>
      <motion.button
        className={`relative w-12 h-6 rounded-full transition-colors ${
          autoNotify ? 'bg-blue-500' : 'bg-gray-600'
        }`}
        onClick={handleToggle}
        whileTap={{ scale: 0.95 }}
        initial={false}
        animate={{ backgroundColor: autoNotify ? '#3B82F6' : '#4B5563' }}
      >
        <motion.div
          className="absolute w-5 h-5 bg-white rounded-full shadow-md"
          initial={false}
          animate={{ 
            left: autoNotify ? '26px' : '3px',
            transition: { type: 'spring', stiffness: 500, damping: 30 }
          }}
        />
      </motion.button>
    </div>
  );
};

export default NotificationToggle; 